{"argv":["python3","-c","import csv,glob,collections
rows=[]
for p in sorted(glob.glob('/task/shard_*.csv')):
    with open(p,newline='',encoding='utf-8') as f:
        r=list(csv.DictReader(f))
    print(p,len(r),sorted(r[0].keys()))
    for d in r: rows.append((p,d))
print('total rows',len(rows))
print('statuses',collections.Counter(d['status'] for p,d in rows))
idc=collections.Counter(d['record_id'] for p,d in rows)
dup={k:v for k,v in idc.items() if v>1}
print('unique ids',len(idc),'dup ids',len(dup))
conf=[]
for k in dup:
    recs=set((d['amount_cents'],d['status']) for p,d in rows if d['record_id']==k)
    if len(recs)>1: conf.append((k,sorted(recs)))
print('conflicting dup ids',len(conf))
for c in conf[:20]: print(c)
print('dup multiplicities',collections.Counter(dup.values()))
print('blank/odd amount fields',[(d['record_id'],repr(d['amount_cents']),d['status']) for p,d in rows if not d['amount_cents'].lstrip('-').isdigit()])
"]}

