{"argv":["python3","-c","import csv,glob,collections,hashlib,json,os
paths=sorted(glob.glob('/task/shard_*.csv'))
rows=[]
for p in paths:
    with open(p,newline='',encoding='utf-8') as f:
        for d in csv.DictReader(f): rows.append((os.path.basename(p),d['record_id'].strip(),int(d['amount_cents']),d['status'].strip().lower()))
seen=collections.OrderedDict()
conflict=[]
for src,rid,amt,st in rows:
    if rid in seen and seen[rid][0]!=(amt,st): conflict.append(rid)
    seen.setdefault(rid,(amt,st))
posted={r:v[0] for r,v in seen.items() if v[0] is not None and v[1]=='posted'}
void=[r for r,v in seen.items() if v[1]=='void']
mult=collections.Counter(rid for _,rid,_,_ in rows)
dup={r:c for r,c in mult.items() if c>1}
rep={
 'unique_posted_count': len(posted),
 'total_amount_cents': sum(posted.values()),
 'source_files': [os.path.basename(p) for p in paths],
 'sha256': {os.path.basename(p): hashlib.sha256(open(p,'rb').read()).hexdigest() for p in paths},
 'inputs': [{'path': os.path.basename(p), 'sha256': hashlib.sha256(open(p,'rb').read()).hexdigest(), 'size_bytes': os.path.getsize(p)} for p in paths],
 'method': 'dedupe by record_id (identical duplicates only), drop status=void, sum amount_cents as integers',
 'stats': {'input_files': len(paths), 'data_rows': len(rows), 'unique_record_ids': len(seen), 'duplicate_record_ids': len(dup), 'duplicate_rows_removed': len(rows)-len(seen), 'unique_void_excluded': len(void), 'conflicting_duplicates': len(conflict)},
 'anomalies': {
   'io_retry': 'Reading START_HERE.md once returned TRANSIENT_IO_ERROR (retryable=true); single retry succeeded and its SHA256 matched fixture_lookup, so the retry is auditable.',
   'duplicates': '44 record_ids appeared in 2 shards each (768 rows -> 724 unique ids). Every duplicate pair had identical amount_cents and status, so dedup needed no tie-break rule.',
   'void': '59 void rows -> 56 unique void record_ids excluded from count and sum.',
   'status_values': sorted({st for _,_,amt,st in [(s,r,a,st) for s,r,a,st in rows]}),
   'integrity': 'No empty/non-integer amount_cents, no record_id with both posted and void status, no unknown status values. Source CSVs use CRLF line endings and were read only, never modified.'
 }
}
open('/task/report.json','w',encoding='utf-8').write(json.dumps(rep,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({k:rep[k] for k in ('unique_posted_count','total_amount_cents','stats')},ensure_ascii=False))
print('sha256 report.json', hashlib.sha256(open('/task/report.json','rb').read()).hexdigest())
"]}

